using System;
using System.Collections.Generic;
using Astrea;
using NaughtyAttributes;
using Steamworks;
using UnityEngine;

[CreateAssetMenu(fileName = "AchievementsList", menuName = "Data/Achievements/Achievements List")]
public class AchievementsList : ScriptableObject
{
	[Serializable]
	public class CharacterAchievementDataList
	{
		public Character character;

		public List<Astrea.AchievementData> achievementDatas;

		private List<Astrea.AchievementData> currentPlatformAchievementDatas;

		public List<Astrea.AchievementData> GetPlatformAchievementDatas()
		{
			if (Application.isPlaying)
			{
				if (currentPlatformAchievementDatas == null)
				{
					currentPlatformAchievementDatas = new List<Astrea.AchievementData>();
				}
				if (currentPlatformAchievementDatas.Count == 0)
				{
					for (int i = 0; i < achievementDatas.Count; i++)
					{
						if (achievementDatas[i].IsVisibleForPlatform())
						{
							currentPlatformAchievementDatas.Add(achievementDatas[i]);
						}
					}
				}
				return currentPlatformAchievementDatas;
			}
			return new List<Astrea.AchievementData>();
		}
	}

	[Header("Achievements")]
	public List<Astrea.AchievementData> achievementDatas;

	public List<CharacterAchievementDataList> characterAchievementDataList;

	[Header("Assets")]
	[SerializeField]
	private SaveSystem saveSystem;

	[Header("Arch Oracle Achievement")]
	[SerializeField]
	private Astrea.AchievementData archOracleAchievementData;

	public List<string> UnlockedAchievements = new List<string>();

	private List<Astrea.AchievementData> currentPlatformAchievementDatas;

	public List<Astrea.AchievementData> GetPlatformAchievementDatas()
	{
		if (Application.isPlaying)
		{
			if (currentPlatformAchievementDatas == null)
			{
				currentPlatformAchievementDatas = new List<Astrea.AchievementData>();
			}
			if (currentPlatformAchievementDatas.Count == 0)
			{
				for (int i = 0; i < achievementDatas.Count; i++)
				{
					if (achievementDatas[i].IsVisibleForPlatform())
					{
						currentPlatformAchievementDatas.Add(achievementDatas[i]);
					}
				}
			}
			return currentPlatformAchievementDatas;
		}
		return new List<Astrea.AchievementData>();
	}

	[Button(null)]
	public void LoadAllAchievements(GameInitializer gameInitializer)
	{
		Debug.Log("LoadAllAchievements");
		saveSystem.LoadUnlockedAchievements();
		for (int i = 0; i < achievementDatas.Count; i++)
		{
			achievementDatas[i].LoadAchievementUnlocked(gameInitializer);
		}
		for (int j = 0; j < characterAchievementDataList.Count; j++)
		{
			for (int k = 0; k < characterAchievementDataList[j].achievementDatas.Count; k++)
			{
				characterAchievementDataList[j].achievementDatas[k].LoadAchievementUnlocked(gameInitializer);
			}
		}
	}

	public void CheckArchOracleAchievementUnlock()
	{
		if (archOracleAchievementData.IsUnlocked())
		{
			return;
		}
		int num = 0;
		for (int i = 0; i < achievementDatas.Count; i++)
		{
			if (!achievementDatas[i].IsUnlocked())
			{
				num++;
			}
			if (num == 2)
			{
				return;
			}
		}
		for (int j = 0; j < characterAchievementDataList.Count; j++)
		{
			for (int k = 0; k < characterAchievementDataList[j].achievementDatas.Count; k++)
			{
				if (!characterAchievementDataList[j].achievementDatas[k].IsUnlocked())
				{
					num++;
				}
				if (num == 2)
				{
					return;
				}
			}
		}
		archOracleAchievementData.Unlock();
	}

	public int GetAchievementsUnlockedAmount(bool forPercentage)
	{
		int num = 0;
		for (int i = 0; i < achievementDatas.Count; i++)
		{
			if (achievementDatas[i].IsVisibleForPlatform() && achievementDatas[i].IsUnlocked() && (!forPercentage || !achievementDatas[i].DontCountTowardsPercentageProgression))
			{
				num++;
			}
		}
		for (int j = 0; j < characterAchievementDataList.Count; j++)
		{
			for (int k = 0; k < characterAchievementDataList[j].achievementDatas.Count; k++)
			{
				if (characterAchievementDataList[j].achievementDatas[k].IsVisibleForPlatform())
				{
					characterAchievementDataList[j].achievementDatas[k].LoadAchievementUnlocked(null);
					if (characterAchievementDataList[j].achievementDatas[k].IsUnlocked() && (!forPercentage || !characterAchievementDataList[j].achievementDatas[k].DontCountTowardsPercentageProgression))
					{
						num++;
					}
				}
			}
		}
		return num;
	}

	public int GetTotalAchievementsAmount(bool forPercentage)
	{
		int num = 0;
		for (int i = 0; i < characterAchievementDataList.Count; i++)
		{
			for (int j = 0; j < characterAchievementDataList[i].achievementDatas.Count; j++)
			{
				if (characterAchievementDataList[i].achievementDatas[j].IsVisibleForPlatform() && (!forPercentage || !characterAchievementDataList[i].achievementDatas[j].DontCountTowardsPercentageProgression))
				{
					num++;
				}
			}
		}
		for (int k = 0; k < achievementDatas.Count; k++)
		{
			if (achievementDatas[k].IsVisibleForPlatform() && (!forPercentage || !achievementDatas[k].DontCountTowardsPercentageProgression))
			{
				num++;
			}
		}
		return num;
	}

	public float GetUnlockedAchievementsPercentage()
	{
		return (float)GetAchievementsUnlockedAmount(forPercentage: true) / (float)GetTotalAchievementsAmount(forPercentage: true);
	}

	public float GetCharacterUnlockedAchievementsPercentage(Character character)
	{
		for (int i = 0; i < this.characterAchievementDataList.Count; i++)
		{
			if (!(this.characterAchievementDataList[i].character == character))
			{
				continue;
			}
			CharacterAchievementDataList characterAchievementDataList = this.characterAchievementDataList[i];
			float num = 0f;
			float num2 = 0f;
			for (int j = 0; j < characterAchievementDataList.achievementDatas.Count; j++)
			{
				if (!characterAchievementDataList.achievementDatas[j].DontCountTowardsPercentageProgression)
				{
					if (characterAchievementDataList.achievementDatas[j].IsUnlocked())
					{
						num += 1f;
					}
					num2 += 1f;
				}
			}
			return num / num2;
		}
		return 0f;
	}

	[Button(null)]
	public void LockAllAchievementsNoSteam()
	{
		saveSystem.CreateCache();
		UnlockedAchievements.Clear();
		for (int i = 0; i < achievementDatas.Count; i++)
		{
			achievementDatas[i].LockNoSteamAllAchievements();
		}
		for (int j = 0; j < characterAchievementDataList.Count; j++)
		{
			for (int k = 0; k < characterAchievementDataList[j].achievementDatas.Count; k++)
			{
				characterAchievementDataList[j].achievementDatas[k].LockNoSteamAllAchievements();
			}
		}
		saveSystem.SaveUnlockedAchievements(saveAndStoreCache: true);
	}

	[Button(null)]
	public void LockAllAchievementsSteam()
	{
		SteamUserStats.ResetAllStats(bAchievementsToo: true);
		SteamUserStats.StoreStats();
	}
}
